INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','mcq','Fever is defined as an axillary temperature above which value according to the Ghana Standard Treatment Guidelines 2017?','["A. 37.5\u00b0C", "B. 37.0\u00b0C", "C. 38.0\u00b0C", "D. 38.5\u00b0C"]','A','The Ghana STG 2017 defines fever as an axillary temperature above 37.5°C when measured after keeping the thermometer in place for 3 minutes. Fever above 38°C often needs urgent attention, especially in restless or delirious patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','mcq','Which of the following is the MOST important initial investigation in a patient presenting with fever in a malaria-endemic region such as Ghana?','["A. Chest X-ray","B. Blood film for malaria parasites or Rapid Diagnostic Test (RDT)","C. Urine culture","D. Liver function tests"]','B','In malaria-endemic Ghana, fever must be investigated with a blood film for malaria parasites or a Rapid Diagnostic Test (RDT) as first priority. The Ghana STG states not every fever is due to malaria or typhoid, but malaria must be excluded promptly in all febrile patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','easy','mcq','A 25-year-old presents with fever for 3 days, rigors, and sweating. Blood film is negative for malaria. Which of the following diagnoses should be considered next?','["A. Viral upper respiratory tract infection only", "B. Malignant hyperthermia", "C. Typhoid fever, urinary tract infection, or pneumonia", "D. Drug fever from recent antibiotic use"]','C','When malaria is excluded in a febrile patient with rigors and sweating, the differential should include typhoid fever, urinary tract infections, pneumonia, and other bacterial infections. The Ghana STG emphasises that not every fever is malaria and directs clinicians to appropriate sections based on accompanying symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','mcq','Fever persisting for more than how many days despite treatment should be classified as Pyrexia of Unknown Origin (PUO) and referred for further investigation according to Ghana STG 2017?','["A. 5 days", "B. 7 days", "C. 14 days", "D. 10 days"]','D','The Ghana STG 2017 states that fever persisting for more than 10 days in spite of treatment should be considered pyrexia of unknown origin (PUO) and referred for further investigation. Classic PUO definition by Petersdorf requires fever >38.3°C for >3 weeks, but the Ghana guideline uses a more pragmatic 10-day threshold for referral.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','mcq','A 4-year-old child is brought in with fever of 39°C. The mother says aspirin was given at home to reduce the fever. What is the MOST important concern regarding this?','["A. Aspirin use in children under 16 years carries risk of Reye''s syndrome", "B. Aspirin is under-dosed for children", "C. Aspirin is an appropriate antipyretic for children", "D. Aspirin should be combined with ibuprofen in febrile children"]','A','Aspirin (acetylsalicylic acid) is contraindicated in children under 16 years due to the risk of Reye''s syndrome — a rare but serious condition causing liver and brain damage, particularly when used in viral illnesses. The Ghana STG 2017 explicitly states: "DO NOT give Aspirin to children under the age of 16 years." Paracetamol is the preferred antipyretic in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','mcq','Which of the following best characterises the fever pattern classically associated with Plasmodium vivax malaria?','["A. Continuous fever without periodicity","B. Tertian periodicity (fever every 48 hours)","C. Quotidian fever (daily)","D. Quartan periodicity (fever every 72 hours)"]','B','Plasmodium vivax and P. ovale cause tertian malaria with fever paroxysms every 48 hours (every third day), corresponding to the erythrocytic schizogony cycle. P. malariae causes quartan fever (every 72 hours). P. falciparum often causes continuous or irregular fever. Understanding fever periodicity helps narrow the differential diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','mcq','A returning traveller from West Africa presents with intermittent fever, chills, and headache 2 weeks after return. Initial RDT for malaria is negative. What is the MOST appropriate next step?','["A. Discharge with oral paracetamol", "B. Start empirical malaria treatment immediately", "C. Repeat thick and thin blood films 12-24 hours later", "D. Perform chest X-ray as the priority investigation"]','C','A negative RDT does not exclude malaria, especially in low-parasitaemia infections. Thick and thin blood film microscopy should be repeated every 12-24 hours for at least 3 smears before malaria is excluded. Malaria remains the most important diagnosis to exclude in a febrile traveller returning from West Africa within 3 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','medium','mcq','Which of the following combinations of fever, Faget''s sign (slow pulse relative to fever), and jaundice should raise suspicion for which diagnosis in West Africa?','["A. Dengue fever", "B. Ebola virus disease", "C. Lassa fever", "D. Yellow fever"]','D','Yellow fever classically presents with fever followed by apparent recovery, then jaundice, haemorrhage, and Faget''s sign (relative bradycardia despite high fever). Ghana and West Africa are endemic for yellow fever. Vaccination is the key preventive measure. Lassa fever presents with haemorrhage without the characteristic biphasic course and bradycardia. Ebola presents with severe haemorrhagic manifestations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','hard','mcq','A 30-year-old HIV-positive patient on antiretroviral therapy presents with fever for 3 weeks, night sweats, and weight loss. CD4 count is 80 cells/µL. Chest X-ray shows miliary infiltrates. Which investigation is MOST diagnostic?','["A. Sputum Xpert MTB/RIF and bone marrow or lymph node biopsy", "B. Blood culture for bacteria", "C. HIV viral load", "D. Serum procalcitonin"]','A','In an HIV patient with CD4 <200 cells/µL presenting with fever, night sweats, weight loss, and miliary infiltrates, disseminated TB is the most likely diagnosis. Sputum Xpert MTB/RIF combined with biopsy of the most accessible site (bone marrow, lymph node) gives the highest diagnostic yield. Miliary TB is a common AIDS-defining illness in sub-Saharan Africa and carries high mortality if untreated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Approach to Fever','hard','mcq','A 45-year-old patient presents with fever, rigors, and confusion following a dental extraction 3 days ago. Blood cultures grow Streptococcus viridans. Echocardiography shows a vegetation on the mitral valve. Which complication of fever and bacteraemia does this represent?','["A. Septic arthritis","B. Infective endocarditis","C. Brain abscess","D. Epidural abscess"]','B','This presentation is classic for infective endocarditis (IE) — fever, rigors, altered mentation, and a new cardiac vegetation following a dental procedure with viridans streptococci bacteraemia. The Duke criteria require positive blood cultures plus echocardiographic evidence of endocardial involvement. Treatment requires prolonged IV antibiotics and sometimes surgery. Dental procedures can seed oral flora onto abnormal cardiac valves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','mcq','According to the Ghana Standard Treatment Guidelines 2017, what is the first-line treatment for uncomplicated Plasmodium falciparum malaria in adults?','["A. Artemether-Lumefantrine (AL) for 3 days", "B. Chloroquine for 3 days", "C. Mefloquine single dose", "D. Quinine for 7 days"]','A','Artemether-Lumefantrine (AL/Coartem) is the first-line treatment for uncomplicated P. falciparum malaria in Ghana as per the Ghana STG 2017. It is given over 3 days as 6 doses (at 0, 8, 24, 36, 48, and 60 hours). Artesunate + Amodiaquine (ASAQ) is an alternative first-line option. Chloroquine resistance is widespread in Ghana, making it ineffective against P. falciparum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','mcq','Which Plasmodium species is responsible for the majority of malaria deaths in sub-Saharan Africa, including Ghana?','["A. Plasmodium vivax", "B. Plasmodium falciparum", "C. Plasmodium malariae", "D. Plasmodium ovale"]','B','Plasmodium falciparum is responsible for the vast majority of malaria morbidity and mortality in sub-Saharan Africa, including Ghana. It causes severe malaria, cerebral malaria, severe anaemia, and multi-organ failure. P. vivax is prevalent in Asia and can cause relapsing malaria due to hypnozoites. P. malariae causes quartan fever and can persist for decades. P. ovale is rare in Ghana.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','easy','mcq','Which of the following is a defining feature of SEVERE malaria as opposed to uncomplicated malaria?','["A. Fever above 37.5°C","B. Positive blood film for P. falciparum","C. Impaired consciousness or prostration","D. Mild jaundice with splenomegaly"]','C','Severe malaria is defined by the WHO as P. falciparum infection with one or more clinical or laboratory features of severity, including impaired consciousness (Glasgow Coma Score <11 in adults or Blantyre Coma Score <3 in children), prostration, repeated generalised seizures, respiratory distress, circulatory collapse, abnormal bleeding, jaundice with evidence of vital organ dysfunction, hyperparasitaemia (>5%), hypoglycaemia (<2.2 mmol/L), or severe anaemia (Hb <5 g/dL).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','mcq','A 7-year-old boy with severe malaria and impaired consciousness is brought to a referral centre. According to Ghana STG 2017, what is the recommended parenteral treatment?','["A. IV Chloroquine 25 mg/kg over 8 hours", "B. IV Artemether 3.2 mg/kg stat, then 1.6 mg/kg daily", "C. IM Quinine 20 mg/kg loading dose", "D. IV Artesunate 2.4 mg/kg at 0, 12, and 24 hours, then daily"]','D','IV Artesunate is the first-line treatment for severe malaria in Ghana. The dosing for children >20 kg is 2.4 mg/kg IV/IM at time 0, at 12 hours, at 24 hours, then once daily. For children <20 kg, the dose is 3 mg/kg. Parenteral treatment should be given for at least 24 hours before switching to oral ACT. IV Artesunate is superior to quinine in reducing mortality in severe malaria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','mcq','A pregnant woman in her first trimester is diagnosed with uncomplicated P. falciparum malaria. Which treatment is recommended according to Ghana STG 2017?','["A. Quinine plus Clindamycin for 7 days in first trimester", "B. Artesunate + Amodiaquine \u2014 recommended in all trimesters", "C. Artemether-Lumefantrine \u2014 safe in all trimesters", "D. Withhold treatment until second trimester to avoid teratogenicity"]','A','In the first trimester of pregnancy, quinine plus clindamycin is recommended for uncomplicated malaria because of limited safety data for artemisinin-based therapies in the first trimester. Artesunate-based ACTs (AL, ASAQ) are used in the second and third trimesters. Withholding treatment is dangerous as malaria in pregnancy significantly increases maternal and foetal morbidity and mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','mcq','Which of the following best explains the mechanism by which P. falciparum causes cerebral malaria?','["A. Direct invasion of neurons by merozoites","B. Cytoadherence of parasitised red cells to cerebral microvascular endothelium causing sequestration","C. Neurotoxins released during parasite replication","D. Autoimmune antibodies cross-reacting with brain antigens"]','B','Cerebral malaria results from sequestration — parasitised red blood cells (pRBCs) express PfEMP1 (P. falciparum erythrocyte membrane protein 1) which binds to ICAM-1 and other receptors on cerebral microvascular endothelium. This causes mechanical obstruction, cytokine-mediated inflammation, and disruption of the blood-brain barrier. Direct neuronal invasion does not occur.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','mcq','Intermittent Preventive Treatment in Pregnancy (IPTp) for malaria in Ghana uses which drug?','["A. Chloroquine weekly","B. Mefloquine monthly","C. Sulphadoxine-Pyrimethamine at each antenatal contact after first trimester","D. Artemether-Lumefantrine at booking"]','C','IPTp uses Sulphadoxine-Pyrimethamine (SP) given at each scheduled antenatal care visit after the first trimester (starting from 13 weeks), at least one month apart. Despite increasing SP resistance, it remains effective for IPTp through a mechanism that may include its antimalarial effect and immunomodulatory properties. SP is contraindicated in HIV-positive pregnant women on cotrimoxazole prophylaxis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','medium','mcq','A 3-year-old child with severe malaria develops hypoglycaemia (blood glucose 1.5 mmol/L). What is the immediate treatment?','["A. Oral glucose solution via nasogastric tube", "B. Subcutaneous insulin adjustment", "C. IM glucagon 0.5 mg", "D. IV 10% Dextrose 5 ml/kg bolus over 5 minutes"]','D','Hypoglycaemia in severe malaria (blood glucose <2.2 mmol/L) is a life-threatening complication, especially in children and pregnant women (also a quinine side effect). Immediate treatment is IV 10% Dextrose 5 ml/kg (or 50% Dextrose 1 ml/kg diluted) given over 5 minutes, followed by a glucose infusion. Oral glucose is inappropriate in unconscious patients. Glucagon is used for insulin-induced hypoglycaemia in diabetics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','hard','mcq','A 35-year-old man with G6PD deficiency is diagnosed with Plasmodium vivax malaria. After treating the acute episode, which drug requires particular caution and G6PD screening before use for radical cure?','["A. Primaquine", "B. Chloroquine", "C. Doxycycline", "D. Atovaquone-Proguanil"]','A','Primaquine is required for radical cure of P. vivax and P. ovale malaria because it eliminates dormant liver hypnozoites that cause relapses. However, primaquine causes dose-dependent haemolytic anaemia in G6PD-deficient individuals. G6PD testing is mandatory before initiating primaquine. If G6PD deficiency is present, weekly low-dose primaquine under supervision may be used in some settings. Chloroquine only treats the blood stage but does not eliminate hypnozoites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Malaria','hard','mcq','A patient with suspected severe malaria arrives at a peripheral facility where IV artesunate is not available. According to Ghana STG 2017, what pre-referral treatment should be given before transfer to a higher facility?','["A. Oral Artemether-Lumefantrine as a loading dose","B. IM Artesunate or IM Artemether or IM Quinine as pre-referral treatment","C. Rectal Artesunate suppository in children only","D. No treatment until reaching the referral centre"]','B','The Ghana STG 2017 states that appropriate treatment must be initiated prior to transferring patients with severe malaria. Pre-referral options include IM Artesunate (2.4 mg/kg for >20 kg, 3 mg/kg for <20 kg), IM Artemether (3.2 mg/kg stat), or IM Quinine (10 mg/kg). Rectal artesunate is specifically recommended for children <6 years if no IV/IM access is available. The principle is: treat first, then transfer.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','mcq','What is the standard first-line anti-tuberculosis regimen for new adult pulmonary TB cases in Ghana according to national guidelines?','["A. 2 months of RHZE followed by 4 months of RH", "B. 6 months of Isoniazid and Rifampicin alone", "C. 9 months of Streptomycin and Isoniazid", "D. 6 months of Rifampicin, Ethambutol, and Pyrazinamide"]','A','The standard first-line TB regimen is 2RHZE/4RH: two months of Rifampicin (R), Isoniazid (H), Pyrazinamide (Z), and Ethambutol (E) in the intensive phase, followed by four months of Rifampicin and Isoniazid in the continuation phase. This regimen achieves >90% cure rates in drug-susceptible TB when taken consistently. DOTS (Directly Observed Treatment Short-course) is the recommended strategy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','mcq','Which sputum test has become the recommended rapid diagnostic for TB in Ghana, capable of simultaneously detecting rifampicin resistance?','["A. Ziehl-Neelsen smear microscopy", "B. Xpert MTB/RIF (GeneXpert)", "C. Sputum culture on Lowenstein-Jensen medium", "D. Tuberculin skin test (Mantoux)"]','B','GeneXpert MTB/RIF (Xpert) is a WHO-endorsed rapid molecular test that simultaneously detects M. tuberculosis DNA and rifampicin resistance within 2 hours. It is more sensitive than ZN smear microscopy, especially in HIV-positive patients who often have paucibacillary disease. Ghana''s National TB Programme uses it as the initial diagnostic test. ZN smear is used for treatment monitoring, not initial diagnosis in high-burden settings.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','easy','mcq','A patient on TB treatment develops yellow discolouration of urine. Which drug is responsible and is this a cause for concern?','["A. Ethambutol \u2014 causes hepatotoxicity requiring immediate discontinuation", "B. Pyrazinamide \u2014 causes renal toxicity leading to dark urine", "C. Rifampicin \u2014 causes orange-red discolouration of body fluids, is harmless and expected", "D. Isoniazid \u2014 causes haemoglobin breakdown and haematuria"]','C','Rifampicin causes orange-red discolouration of urine, sweat, tears, and saliva in all patients taking it. This is harmless, expected, and patients should be counselled about it before starting treatment to prevent unnecessary alarm. Contact lenses may be permanently stained. This side effect does not require dose adjustment or discontinuation. It is a very high-yield counselling point for TB treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','mcq','A patient on anti-TB therapy develops bilateral blurring of vision and difficulty distinguishing red from green colours after 6 weeks of treatment. Which drug is the most likely cause?','["A. Rifampicin","B. Isoniazid","C. Pyrazinamide","D. Ethambutol"]','D','Ethambutol causes dose-dependent optic neuritis, presenting as reduced visual acuity, loss of red-green colour discrimination (the earliest and most sensitive sign), and central scotoma. It typically occurs at doses >25 mg/kg/day. Baseline and regular visual acuity and colour vision testing are mandatory. Ethambutol should be stopped immediately if ocular toxicity is suspected. Recovery is usually complete if detected early. Isoniazid causes peripheral neuropathy (prevented by pyridoxine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','mcq','A TB patient on treatment develops peripheral neuropathy (tingling and numbness in hands and feet). Which drug causes this and what is the prevention?','["A. Isoniazid \u2014 prevented by Pyridoxine (Vitamin B6) supplementation", "B. Rifampicin \u2014 prevented by Vitamin D supplementation", "C. Ethambutol \u2014 prevented by Zinc supplementation", "D. Pyrazinamide \u2014 prevented by Folic acid supplementation"]','A','Isoniazid (INH) causes peripheral neuropathy by interfering with pyridoxine (Vitamin B6) metabolism, leading to reduced production of GABA and other neurotransmitters. Prevention: Pyridoxine 25-50 mg/day is co-prescribed with isoniazid, especially in patients at higher risk: malnourished, alcoholics, diabetics, pregnant women, HIV-positive, and the elderly. Treatment of established neuropathy also involves higher dose pyridoxine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','mcq','Which of the following is an indication for extending the TB treatment continuation phase from 4 months to 7 months (total duration 9 months)?','["A. Pulmonary TB with positive sputum at 2 months","B. Extrapulmonary TB affecting the spine (Pott''s disease) or central nervous system","C. TB/HIV co-infection with CD4 count >350 cells/µL","D. TB in patients over 60 years of age"]','B','The WHO and national guidelines recommend extending the continuation phase to 7 months (making total treatment 9 months: 2RHZE/7RH) for TB involving the central nervous system (TB meningitis) and spinal TB (Pott''s disease). The rationale is poor CNS penetration of drugs, higher organism burden in CNS disease, and severity of consequences of relapse. Cavitatory disease with slow sputum conversion may also require extension in some guidelines.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','mcq','In TB/HIV co-infected patients, what is the recommended approach to timing of antiretroviral therapy initiation?','["A. Start ART 6 months after TB treatment completion", "B. Start ART simultaneously with TB treatment on day 1 always", "C. Start ART within 2-8 weeks of starting TB treatment (except in TB meningitis)", "D. Wait for CD4 count >350 before starting ART"]','C','In TB/HIV co-infection, ART should be initiated within 2-8 weeks of starting TB treatment to reduce mortality, regardless of CD4 count. The exception is TB meningitis, where early ART (within 2 weeks) is associated with increased mortality from paradoxical immune reconstitution inflammatory syndrome (IRIS). For TB meningitis, ART is delayed to 4-8 weeks. This is a critical management principle for one of Africa''s most deadly co-infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','medium','mcq','A healthcare worker with a positive Tuberculin Skin Test (TST, Mantoux test, induration >5mm) but no symptoms or radiological evidence of active TB. What is this condition and what is the recommended management?','["A. Active pulmonary TB \u2014 start full 4-drug regimen immediately", "B. False positive \u2014 retest in 3 months", "C. BCG vaccine reaction \u2014 no treatment required", "D. Latent TB Infection (LTBI) \u2014 treat with Isoniazid Preventive Therapy (IPT) for 6 months"]','D','A positive TST (>5 mm in HIV-positive or immunocompromised patients, >10 mm in healthcare workers and contacts) without active disease constitutes Latent TB Infection (LTBI). Treatment with Isoniazid Preventive Therapy (IPT): Isoniazid 300 mg/day for 6 months (or 9 months per WHO) reduces progression to active TB by ~60-90%. Active TB must be excluded before starting IPT. All HIV-positive patients in Ghana should be screened for LTBI and offered IPT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','hard','mcq','A patient with Multi-Drug Resistant TB (MDR-TB) is defined as having resistance to which combination of drugs?','["A. Resistance to at least Isoniazid and Rifampicin", "B. Resistance to Rifampicin alone", "C. Resistance to all four first-line drugs", "D. Resistance to fluoroquinolones and aminoglycosides"]','A','MDR-TB is defined as TB resistant to at least Isoniazid AND Rifampicin — the two most potent first-line anti-TB drugs. Resistance to Rifampicin alone is treated as MDR-TB. XDR-TB (Extensively Drug-Resistant TB) is additionally resistant to any fluoroquinolone AND at least one injectable agent (amikacin, kanamycin, capreomycin). MDR-TB requires 18-24 months of second-line therapy and has significantly worse outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Tuberculosis','hard','mcq','A patient 3 months into TB treatment develops jaundice, dark urine, and raised transaminases (ALT >5x upper limit of normal). Which drugs should be stopped and what is the management?','["A. Stop Ethambutol only; continue the other three drugs","B. Stop all potentially hepatotoxic TB drugs (Rifampicin, Isoniazid, Pyrazinamide) and manage liver toxicity","C. Reduce doses of all four drugs by 50%","D. Continue treatment and add a hepatoprotective agent"]','B','Drug-induced liver injury (DILI) from TB treatment requires stopping the three hepatotoxic drugs: Rifampicin, Isoniazid, and Pyrazinamide. Ethambutol can be continued as it is not hepatotoxic. Management: withhold drugs, monitor LFTs, manage liver failure supportively. Reintroduce drugs one at a time (starting with rifampicin) when LFTs normalise. Pyrazinamide is the most hepatotoxic and may be permanently omitted. This is defined as ALT >5x ULN without symptoms or >3x ULN with jaundice/symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','mcq','What is the recommended first-line antiretroviral therapy (ART) regimen for treatment-naive HIV-positive adults according to Ghana national guidelines?','["A. Tenofovir + Lamivudine + Efavirenz (TDF/3TC/EFV)", "B. Zidovudine + Lamivudine + Nevirapine (AZT/3TC/NVP)", "C. Stavudine + Didanosine + Lopinavir/Ritonavir", "D. Abacavir + Lamivudine + Dolutegravir (ABC/3TC/DTG) for all patients"]','A','Ghana''s national guidelines recommend TDF + 3TC + EFV as the preferred first-line regimen for treatment-naive adults. TDF is preferred over AZT due to better tolerability (less anaemia and lipoatrophy). EFV is preferred over NVP due to lower hepatotoxicity and no requirement for lead-in dosing. In high-income settings, dolutegravir-based regimens are increasingly preferred, but TDF/3TC/EFV remains standard in most African guidelines including Ghana.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','mcq','At what CD4 count threshold is Cotrimoxazole Prophylaxis Therapy (CPT) recommended for HIV-positive patients in Ghana to prevent opportunistic infections?','["A. CD4 < 500 cells/\u00b5L", "B. CPT is given to all HIV-positive patients regardless of CD4 count", "C. CD4 < 200 cells/\u00b5L", "D. CD4 < 350 cells/\u00b5L"]','B','Ghana''s national guidelines (aligned with WHO recommendations) recommend cotrimoxazole prophylaxis for ALL HIV-positive individuals, regardless of CD4 count, as it prevents Pneumocystis jirovecii pneumonia (PCP), toxoplasmosis, bacterial infections, and malaria. In high-burden settings like Ghana, universal CPT is given from diagnosis until CD4 is consistently >350 cells/µL on ART and the patient is clinically stable (some guidelines say >200).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','easy','mcq','The WHO clinical staging of HIV disease categorises advanced HIV disease (AIDS) as which stage?','["A. WHO Stage 1", "B. WHO Stage 2", "C. WHO Stage 4", "D. WHO Stage 3"]','C','WHO Clinical Stage 4 defines AIDS, characterized by AIDS-defining illnesses including: Pneumocystis pneumonia, cerebral toxoplasmosis, cryptococcal meningitis, CMV retinitis, disseminated Mycobacterium avium complex, oesophageal candidiasis, HIV wasting syndrome, Kaposi''s sarcoma, HIV encephalopathy, disseminated TB, and others. Stage 3 includes severe conditions that are not necessarily AIDS-defining. Knowing the staging criteria is essential for determining ART eligibility and prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','mcq','An HIV-positive patient on TDF/3TC/EFV develops severe dizziness, vivid dreams, and nightmares, predominantly at night, within 2 weeks of starting therapy. Which drug is responsible and what is the management?','["A. Tenofovir (TDF) \u2014 switch to Abacavir", "B. Lamivudine (3TC) \u2014 dose reduction required", "C. All three drugs \u2014 switch to alternative regimen immediately", "D. Efavirenz (EFV) \u2014 CNS side effects, usually self-limiting within 2-4 weeks; take at bedtime"]','D','Efavirenz (EFV) causes CNS side effects in up to 50% of patients in the first weeks: dizziness, vivid dreams, nightmares, insomnia, confusion, and rarely psychosis. These are usually self-limiting within 2-4 weeks. Taking EFV at bedtime on an empty stomach (or low-fat meal) reduces peak plasma levels and minimises CNS effects. Dose reduction is not recommended. Switching is considered only if symptoms are severe, persistent, or there are psychiatric contraindications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','mcq','A 28-year-old HIV-positive woman on ART (TDF/3TC/EFV) discovers she is 8 weeks pregnant. EFV is a teratogen (neural tube defects) in the first trimester. What modification should be made to her ART?','["A. Continue EFV \u2014 current WHO/Ghana guidelines consider it safe throughout pregnancy", "B. Switch EFV to Nevirapine (NVP) or a Protease Inhibitor immediately", "C. Stop all ART until after the first trimester to protect the foetus", "D. Add Folic acid 5 mg daily and continue EFV with close monitoring"]','A','Current WHO guidelines (2016 and beyond) no longer recommend switching away from EFV in pregnancy. Large studies (including PHPT-5, Tsepamo) showed the initial signal of EFV teratogenicity (neural tube defects) was based on very limited data and subsequent large surveillance studies did not confirm a clinically meaningful increased risk. WHO and Ghana guidelines now recommend continuing EFV throughout pregnancy. Stopping ART in pregnancy is harmful. Adding high-dose folic acid before conception is recommended.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','mcq','An HIV patient with CD4 count of 50 cells/µL presents with severe headache, fever, and neck stiffness. CSF India Ink staining shows encapsulated yeast. What is the diagnosis and treatment?','["A. TB meningitis \u2014 start 2RHZE regimen", "B. Cryptococcal meningitis \u2014 Amphotericin B plus Flucytosine induction, then Fluconazole", "C. Bacterial meningitis \u2014 ceftriaxone IV", "D. HIV encephalitis \u2014 increase ART potency"]','B','Cryptococcal meningitis is a leading cause of meningitis-related mortality in HIV patients in Africa. India ink staining of CSF showing encapsulated yeast (Cryptococcus neoformans) confirms the diagnosis. WHO preferred induction: Amphotericin B (deoxycholate 0.7-1 mg/kg/day) plus Flucytosine 25 mg/kg QID for 2 weeks, then Fluconazole 400 mg/day consolidation for 8 weeks, then 200 mg/day maintenance until CD4 >200. Intracranial pressure management (therapeutic lumbar punctures) is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','mcq','What is the most common opportunistic infection in HIV-positive patients in sub-Saharan Africa at CD4 counts below 200 cells/µL?','["A. Cytomegalovirus (CMV) retinitis", "B. Disseminated Mycobacterium avium complex (MAC)", "C. Pneumocystis jirovecii pneumonia (PCP)", "D. Toxoplasma encephalitis"]','C','Pneumocystis jirovecii pneumonia (PCP) remains the most common AIDS-defining opportunistic infection globally, though TB is the leading cause of mortality in HIV patients in Africa. PCP presents with progressive dyspnoea, non-productive cough, fever, and bilateral interstitial infiltrates on CXR. CD4 <200 is the main risk factor. Treatment: high-dose Cotrimoxazole (TMP 15-20 mg/kg/day) for 21 days. Steroids added if PaO2 <70 mmHg. Prophylaxis: Cotrimoxazole 960 mg daily when CD4 <200.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','medium','mcq','A patient who has been on ART for 3 months develops worsening clinical status: new lymphadenopathy and fever, despite a falling HIV viral load. What syndrome does this represent?','["A. ART treatment failure \u2014 switch regimen", "B. Superinfection with a new HIV strain", "C. Drug toxicity from Tenofovir", "D. Immune Reconstitution Inflammatory Syndrome (IRIS)"]','D','Immune Reconstitution Inflammatory Syndrome (IRIS) is a paradoxical worsening of a pre-existing or newly unmasked opportunistic infection as the recovering immune system mounts an inflammatory response. It typically occurs within the first 3 months of ART. Risk factors include: very low CD4 at ART start, high pre-ART viral load, and early ART initiation in the context of an active OI (especially TB or cryptococcal meningitis). Management: continue ART, treat the underlying OI, corticosteroids for severe IRIS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','hard','mcq','An HIV-positive patient on TDF-containing ART develops progressive renal impairment (eGFR declining from 80 to 45 mL/min/1.73m²). Which drug is responsible and what substitution should be made?','["A. Tenofovir Disoproxil Fumarate (TDF) \u2014 switch to Abacavir (ABC) or Tenofovir Alafenamide (TAF)", "B. Efavirenz (EFV) \u2014 switch to Nevirapine (NVP)", "C. Lamivudine (3TC) \u2014 switch to Emtricitabine (FTC)", "D. All NRTIs are nephrotoxic \u2014 switch to NRTI-sparing regimen"]','A','TDF (Tenofovir Disoproxil Fumarate) causes proximal renal tubular toxicity (Fanconi syndrome) and progressive decline in GFR in a small proportion of patients, particularly those with pre-existing renal disease, diabetes, hypertension, or concomitant nephrotoxic drugs. TDF is contraindicated if eGFR <50 mL/min. Abacavir (ABC) is the main substitute (requires HLA-B*5701 screening). TAF (Tenofovir Alafenamide) has lower renal and bone toxicity than TDF and is preferred in patients with renal disease where available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','HIV/AIDS Management','hard','mcq','A 35-year-old patient with HIV presents with progressive cognitive impairment, motor slowing, and personality changes over 6 months. CD4 is 80 cells/µL and viral load is detectable. MRI brain shows diffuse white matter changes. What is the most likely diagnosis?','["A. Cerebral toxoplasmosis", "B. HIV-Associated Neurocognitive Disorder (HAND) / HIV Dementia Complex", "C. Progressive Multifocal Leukoencephalopathy (PML)", "D. Cryptococcal meningitis with white matter involvement"]','B','HIV-Associated Neurocognitive Disorder (HAND), including HIV Dementia Complex (or HIV encephalopathy), results from direct HIV infection of microglia and macrophages in the CNS, causing progressive cognitive, motor, and behavioural decline. CD4 <100 is the main risk factor. MRI shows symmetrical white matter changes. CSF: elevated protein, lymphocytosis, HIV RNA. Treatment: ART with CNS-penetrating drugs (e.g., Zidovudine, Lopinavir/r, Nevirapine have high CNS penetrance scores). Toxoplasmosis causes focal ring-enhancing lesions on MRI; PML causes asymmetric white matter lesions (JC virus).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','mcq','What is the most common bacterial cause of Community-Acquired Pneumonia (CAP) in adults worldwide?','["A. Streptococcus pneumoniae", "B. Staphylococcus aureus", "C. Klebsiella pneumoniae", "D. Legionella pneumophila"]','A','Streptococcus pneumoniae (pneumococcus) is the most common cause of CAP in adults in all age groups and severity categories. It causes lobar or segmental consolidation, often with a productive cough, pleuritic chest pain, rigors, and high fever. Rusty (blood-tinged) sputum is characteristic. Klebsiella is common in alcoholics and diabetics. Legionella causes atypical pneumonia. Staphylococcus aureus causes post-influenza pneumonia or haematogenous pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','mcq','According to the Ghana STG 2017, what is the first-line antibiotic for mild Community-Acquired Pneumonia (CAP) managed as an outpatient?','["A. Ceftriaxone IV 1g daily","B. Amoxicillin oral 500 mg 8 hourly for 5-7 days","C. Ciprofloxacin oral 500 mg 12 hourly","D. Azithromycin alone 500 mg daily for 5 days"]','B','Mild CAP (CURB-65 score 0-1) can be treated as an outpatient with oral Amoxicillin 500 mg three times daily for 5-7 days. Amoxicillin covers the most common pathogen (S. pneumoniae). For atypical pathogen coverage (Mycoplasma, Chlamydophila), Azithromycin or a macrolide is added. Ceftriaxone is reserved for severe or hospitalised CAP. Ciprofloxacin has poor pneumococcal activity and should not be used as monotherapy for CAP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','easy','mcq','The CURB-65 score is used to assess severity of Community-Acquired Pneumonia. What does each letter stand for?','["A. Crepitations, Urea, Respiratory rate, Blood pressure, age 65", "B. Cyanosis, Urea, Radiograph consolidation, Bradycardia, age 65", "C. Confusion, Urea >7 mmol/L, Respiratory rate \u226530/min, Blood pressure (systolic <90 or diastolic \u226460), age \u226565", "D. Confusion, Urea, Renal failure, Blood gases, age 65"]','C','CURB-65: Confusion (new), Urea >7 mmol/L, Respiratory rate ≥30/min, Blood pressure (systolic <90 mmHg or diastolic ≤60 mmHg), age ≥65. Score 0-1: outpatient; Score 2: consider hospital; Score 3-5: severe, consider ICU. PSI (Pneumonia Severity Index) is an alternative, more detailed scoring tool. CURB-65 is widely used in low-resource settings for its simplicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','mcq','A 22-year-old university student presents with 2 weeks of dry cough, low-grade fever, and headache. Chest X-ray shows patchy bilateral infiltrates disproportionate to mild symptoms. Cold agglutinin test is positive. Which organism is most likely responsible?','["A. Streptococcus pneumoniae", "B. Haemophilus influenzae", "C. Legionella pneumophila", "D. Mycoplasma pneumoniae"]','D','Mycoplasma pneumoniae causes atypical (walking) pneumonia, common in young adults and close communities. Features: gradual onset, dry cough, mild symptoms disproportionate to radiological findings ("atypical" pattern), extrapulmonary manifestations (rash, haemolytic anaemia). Cold agglutinins (IgM antibodies against RBC I antigen) are positive in >50%. Treatment: Macrolides (Azithromycin) or Doxycycline. Beta-lactams are ineffective (Mycoplasma lacks a cell wall).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','mcq','A 60-year-old diabetic male presents with severe pneumonia with lobar consolidation of the right upper lobe. He has blood-stained "currant jelly" sputum, and the X-ray shows a "bulging fissure" sign. Which pathogen is most likely?','["A. Klebsiella pneumoniae", "B. Streptococcus pneumoniae", "C. Pseudomonas aeruginosa", "D. Staphylococcus aureus"]','A','Klebsiella pneumoniae classically causes severe pneumonia in alcoholics, diabetics, and the immunocompromised. Features: upper lobe consolidation, "currant jelly" (blood-stained, mucoid) sputum due to tissue necrosis, and the "bulging fissure" sign on CXR (dense infiltrate causing expansion of the affected lobe pushing the fissure downward). It carries high mortality. Treatment: 3rd-generation cephalosporins or aminoglycosides; carbapenem for ESBL-producing strains.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','mcq','A patient with severe CAP (CURB-65 score 4) is admitted. Which antibiotic combination is appropriate for empirical treatment of severe hospitalised CAP requiring ICU care?','["A. Amoxicillin 500 mg oral three times daily","B. Co-amoxiclav IV plus Azithromycin IV, or Ceftriaxone IV plus Azithromycin IV","C. Ciprofloxacin IV alone","D. Metronidazole IV plus Gentamicin IV"]','B','Severe CAP requiring hospitalisation/ICU should be treated with a beta-lactam (Ceftriaxone 1-2 g IV daily or Co-amoxiclav IV) PLUS a macrolide (Azithromycin IV 500 mg daily) or respiratory fluoroquinolone (Levofloxacin). Combination therapy covering both typical (pneumococcus) and atypical organisms (Mycoplasma, Legionella) reduces mortality in severe CAP. Ciprofloxacin monotherapy is inadequate for pneumococcal CAP. Metronidazole/Gentamicin does not cover respiratory pathogens adequately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','mcq','A 5-year-old child presents with acute onset of barking (croupy) cough, inspiratory stridor, and low-grade fever. Which diagnosis and treatment is most appropriate?','["A. Acute epiglottitis \u2014 immediate intubation", "B. Bacterial pneumonia \u2014 IV Ampicillin", "C. Croup (laryngotracheobronchitis) \u2014 nebulised Adrenaline and systemic Dexamethasone", "D. Whooping cough \u2014 Erythromycin for 14 days"]','C','Viral croup (laryngotracheobronchitis) is the most common cause of acute stridor in children 6 months to 3 years, caused by parainfluenza virus. Features: seal-bark cough, inspiratory stridor, low-grade fever, mild respiratory distress. Treatment: Dexamethasone 0.15-0.6 mg/kg oral/IM (single dose) reduces severity and readmission; nebulised Adrenaline (1:1000, 5 mL) provides temporary relief in moderate-severe croup. Epiglottitis causes a toxic child who refuses to swallow and drools, requires airway management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','medium','mcq','Which antibiotic is recommended for treatment of pertussis (whooping cough) and also for post-exposure prophylaxis of household contacts?','["A. Amoxicillin for 10 days", "B. Ciprofloxacin for 7 days", "C. Ceftriaxone IV for 7 days", "D. Azithromycin for 5 days (preferred) or Erythromycin for 14 days"]','D','Pertussis (caused by Bordetella pertussis) is treated with macrolide antibiotics: Azithromycin 500 mg on Day 1 then 250 mg for 4 days (preferred for tolerability), or Erythromycin 500 mg QID for 14 days, or Clarithromycin 500 mg BD for 7 days. Treatment shortens infectivity but may not shorten disease duration if started in the paroxysmal phase. Post-exposure prophylaxis with same macrolide regimen is recommended for all household contacts. Trimethoprim-Sulfamethoxazole is an alternative for macrolide-intolerant patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','hard','mcq','A patient with HIV (CD4 30 cells/µL) presents with progressive dyspnoea over 3 weeks, dry cough, and fever. CXR shows bilateral perihilar "ground glass" opacification. Lactate dehydrogenase (LDH) is markedly elevated. Which organism and treatment is indicated?','["A. Pneumocystis jirovecii (PCP) \u2014 high-dose Cotrimoxazole plus Prednisolone if PaO2 <70 mmHg", "B. Streptococcus pneumoniae \u2014 Amoxicillin IV", "C. Mycobacterium tuberculosis \u2014 start 4-drug TB regimen", "D. Cytomegalovirus \u2014 IV Ganciclovir"]','A','PCP (Pneumocystis jirovecii pneumonia) classically presents in severe immunocompromised (CD4 <200) with: insidious dyspnoea, dry cough, fever, bilateral perihilar ground-glass opacification on CXR, and markedly elevated LDH (>500 U/L). First-line treatment: High-dose Cotrimoxazole (Trimethoprim 15-20 mg/kg/day in 3 divided doses) for 21 days. Adjunctive Prednisolone 40 mg BD for 5 days then taper if PaO2 <70 mmHg or A-a gradient >35 mmHg reduces mortality significantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Respiratory Infections','hard','mcq','A 70-year-old man develops fever, confusion, respiratory failure, hyponatraemia, and elevated creatinine 5 days after attending a hotel conference. Urine Legionella antigen is positive. Which antibiotic is indicated?','["A. Benzylpenicillin IV","B. Azithromycin IV or Levofloxacin IV","C. Amoxicillin oral","D. Ceftriaxone IV alone"]','B','Legionella pneumophila (Legionnaire''s disease) causes severe atypical pneumonia with multi-system involvement: hyponatraemia, confusion, diarrhoea, elevated LFTs, and renal impairment (Pontiac fever is milder self-limiting form). Source: aerosolised water from cooling towers, hotel water systems, air conditioning. Diagnosis: urinary Legionella antigen (rapid, specific for serogroup 1). Treatment: Azithromycin IV 500 mg daily or Levofloxacin IV 750 mg daily. Beta-lactams are ineffective (Legionella is an intracellular pathogen).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','mcq','A 2-year-old child presents with acute watery diarrhoea for 2 days, vomiting, and mild dehydration. No blood in stool. No fever. Which is the most likely cause and initial management?','["A. Rotavirus \u2014 oral rehydration therapy (ORS) and zinc supplementation", "B. Bacterial dysentery \u2014 start antibiotics immediately", "C. Giardia lamblia \u2014 metronidazole for 7 days", "D. Cholera \u2014 IV fluids and tetracycline"]','A','Viral gastroenteritis (rotavirus is most common in children <5 years in developing countries) presents with watery diarrhoea without blood, vomiting, and mild fever. Treatment is supportive: Oral Rehydration Solution (ORS) for rehydration, Zinc 20 mg/day for 10-14 days in children (reduces severity and duration), and continued feeding. Antibiotics are NOT indicated for viral diarrhoea. Blood in stool (dysentery) indicates bacterial cause requiring antibiotics. The Ghana STG emphasises that viral diarrhoea in children should NOT be treated with antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','mcq','Which oral rehydration solution formulation is recommended by the WHO and Ghana STG for treating children with non-severe diarrhoea and dehydration?','["A. Standard WHO ORS (90 mmol/L sodium)","B. Reduced-osmolarity WHO ORS (75 mmol/L sodium)","C. Sports drinks (isotonic, high glucose)","D. Plain water with added table salt"]','B','The reduced-osmolarity WHO ORS (75 mmol/L sodium, 75 mmol/L glucose, 311 mOsm/L) is recommended because it reduces stool output, vomiting, and need for IV fluids compared to the original high-osmolarity ORS. It is the standard globally and in Ghana. Sports drinks have inappropriate glucose-to-sodium ratios. Plain water with salt is not sterile, poorly mixed, and carries risk of hyper- or hyponatraemia. ORS should be given frequently in small amounts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','easy','mcq','Typhoid fever (enteric fever) is caused by which organism and what is the clinical hallmark finding on physical examination?','["A. Vibrio cholerae \u2014 rice-water stools and rapid dehydration", "B. Campylobacter jejuni \u2014 bloody diarrhoea and high fever", "C. Salmonella typhi \u2014 rose spots on the abdomen and relative bradycardia", "D. Shigella dysenteriae \u2014 tenesmus and bloody mucoid stools"]','C','Typhoid fever is caused by Salmonella typhi (or S. paratyphi). Clinical hallmarks: stepwise fever rising over weeks, headache, abdominal pain/distension, relative bradycardia (Faget''s sign — pulse lower than expected for the degree of fever), and rose spots (faint salmon-coloured macules on the trunk, seen in <30% of patients). Complications include intestinal perforation and haemorrhage. Diagnosis: blood culture (gold standard in week 1), Widal test (limited specificity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','mcq','A 25-year-old presents with profuse watery "rice-water" stools, vomiting, and rapid dehydration after attending a community funeral feast. No fever. Which organism and treatment is indicated?','["A. Rotavirus \u2014 ORS only", "B. Shigella \u2014 Ciprofloxacin for 3 days", "C. Salmonella typhi \u2014 Ciprofloxacin for 14 days", "D. Vibrio cholerae \u2014 rapid IV rehydration and Doxycycline or Azithromycin"]','D','Cholera (Vibrio cholerae) causes profuse painless watery "rice-water" stools (resembling water with small white flecks of mucus) and vomiting without fever, capable of causing death from dehydration within hours. Treatment: rapid IV replacement with Ringer''s Lactate or Normal Saline (100 ml/kg over 3 hours for severe dehydration), followed by ORS. Antibiotics (Doxycycline 300 mg single dose, or Azithromycin for children/pregnant women) reduce stool volume and duration. Cholera is a notifiable disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','mcq','Which antibiotic is recommended for treating typhoid fever in Ghana per STG 2017 guidelines?','["A. Ciprofloxacin 500 mg 12 hourly for 10-14 days or Azithromycin 500 mg daily for 7 days", "B. Amoxicillin 500 mg 8 hourly for 14 days", "C. Metronidazole for 10 days", "D. Ceftriaxone IV only for all typhoid cases"]','A','The Ghana STG 2017 recommends Ciprofloxacin or Azithromycin for typhoid fever. Ciprofloxacin (500 mg BD for 10-14 days) is the preferred first-line where fluoroquinolone-susceptible strains predominate. Azithromycin (500 mg daily for 7 days) is used for fluoroquinolone-resistant strains or in children/pregnancy. Ceftriaxone IV (2 g daily for 10-14 days) is for severe typhoid or MDR strains. Amoxicillin resistance is now widespread. The Widal test is unreliable; blood culture is the gold standard.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','mcq','A 35-year-old patient on broad-spectrum antibiotics for 10 days develops severe watery diarrhoea with mucus, abdominal pain, and fever. Sigmoidoscopy shows pseudomembranes. Which organism is responsible and what is the treatment?','["A. Campylobacter jejuni — Erythromycin","B. Clostridioides difficile (C. diff) — Oral Vancomycin or Oral Metronidazole for non-severe disease","C. Salmonella non-typhoidal — Ciprofloxacin","D. Entamoeba histolytica — Metronidazole plus Diloxanide furoate"]','B','Clostridioides difficile infection (CDI) occurs after antibiotic-associated disruption of gut flora, allowing C. diff overgrowth and toxin production. Classic triad: diarrhoea, fever, abdominal pain after antibiotics. Pseudomembranes on colonoscopy are pathognomonic. Treatment: STOP the inciting antibiotic. Non-severe CDI: Oral Metronidazole 500 mg TID for 10 days. Severe CDI: Oral Vancomycin 125-500 mg QID for 10 days (preferred). Recurrent CDI: Fidaxomicin or faecal microbiota transplantation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','mcq','Which of the following presentations should prompt empirical antibiotic treatment in a patient with acute diarrhoea?','["A. Watery diarrhoea for 1 day with mild nausea in a healthy adult", "B. Loose stools for 3 days following a change in diet", "C. Dysentery (bloody diarrhoea) with high fever and severe abdominal pain", "D. Diarrhoea following travel to a rural area without fever"]','C','Empirical antibiotics are indicated for: dysentery (bloody diarrhoea), severe febrile illness, immunocompromised patients, suspected cholera with severe dehydration, and elderly patients with systemic illness. Watery diarrhoea in a healthy adult is usually viral and self-limiting; antibiotics are not indicated. The Ghana STG emphasises avoiding antibiotics in uncomplicated diarrhoea in children, where viral aetiology predominates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','medium','mcq','A 40-year-old presents with right upper quadrant pain, fever, and hepatomegaly. Ultrasound shows a hypoechoic lesion in the right lobe of the liver. Amoebic serology is positive. What is the treatment?','["A. Surgical drainage as the primary treatment", "B. Ciprofloxacin and metronidazole combination for 14 days", "C. Chloroquine alone for 3 weeks", "D. Metronidazole 800 mg 8 hourly for 5-10 days followed by Diloxanide Furoate 500 mg 8 hourly for 10 days"]','D','Amoebic liver abscess (caused by Entamoeba histolytica) presents with fever, right upper quadrant pain, hepatomegaly, and characteristic "anchovy paste" pus on aspiration. Treatment: Metronidazole (800 mg TID for 10 days or 2.4 g/day for 3 days) kills tissue trophozoites. Followed by a luminal amoebicide: Diloxanide furoate 500 mg TID for 10 days (or Paromomycin) to eradicate intestinal cysts and prevent relapse. Surgical drainage is reserved for complicated cases (large abscess >5 cm, no response to metronidazole, secondary bacterial infection, imminent rupture).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','hard','mcq','A 15-year-old develops severe abdominal pain and rigidity 3 weeks into typhoid fever. Erect abdominal X-ray shows free air under the diaphragm. What complication has occurred and what is the management?','["A. Intestinal perforation \u2014 emergency surgical repair plus IV antibiotics (Ceftriaxone and Metronidazole)", "B. Paralytic ileus \u2014 conservative management", "C. Typhoid hepatitis \u2014 increased antibiotic dose", "D. Toxic megacolon \u2014 IV steroids and bowel rest"]','A','Intestinal perforation is a life-threatening complication of typhoid fever, typically occurring in the 3rd week. The Peyer''s patches in the terminal ileum become necrotic and perforate, causing peritonitis. Free air under the diaphragm on erect chest or abdominal X-ray confirms the diagnosis. Management: Emergency surgical repair (primary closure or resection), IV Ceftriaxone plus Metronidazole for peritonitis, fluid resuscitation, and supportive care. Mortality is high without prompt surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Gastrointestinal Infections','hard','mcq','A 6-month-old infant presents with profuse watery diarrhoea (10 stools/day), sunken eyes, absent tears, very reduced skin turgor, and lethargy. What degree of dehydration is this and what IV fluid should be given?','["A. Mild dehydration (<5%) — oral rehydration sufficient","B. Severe dehydration (>10%) — IV Ringer''s Lactate 100 ml/kg over 3 hours (Plan C)","C. Moderate dehydration (5-10%) — increased ORS over 4 hours","D. No dehydration — continue breastfeeding only"]','B','Severe dehydration (>10%) in children presents with: very sunken eyes, no tears, very poor skin turgor (skin pinch goes back very slowly), cold extremities, weak rapid pulse, lethargy. WHO Plan C: IV Ringer''s Lactate 100 ml/kg in infants <12 months: 30 ml/kg in first 1 hour, then 70 ml/kg over next 5 hours. If IV access not possible, nasogastric ORS or intraosseous access can be used. Reassess after each infusion. Signs of severe dehydration with shock require immediate resuscitation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','mcq','What is the most common causative organism of community-acquired urinary tract infections (UTIs)?','["A. Escherichia coli", "B. Staphylococcus aureus", "C. Klebsiella pneumoniae", "D. Pseudomonas aeruginosa"]','A','Escherichia coli accounts for approximately 80% of community-acquired UTIs. It ascends from the periurethral area and colonises the bladder, facilitated by urovirulence factors including P-fimbriae (attach to uroepithelium), flagella, and toxins. Other common pathogens: Klebsiella (10%), Staphylococcus saprophyticus (young women, 5-15%), Enterococcus, Proteus mirabilis. Pseudomonas is associated with hospital-acquired UTIs, catheterisation, and structural abnormalities.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','mcq','A 24-year-old woman presents with dysuria, frequency, and urgency for 2 days. No fever, no loin pain. Urine dipstick: leucocytes positive, nitrites positive. What is the diagnosis and first-line treatment?','["A. Pyelonephritis — IV Ceftriaxone for 14 days","B. Uncomplicated lower UTI (cystitis) — Nitrofurantoin or Trimethoprim for 3-7 days","C. Asymptomatic bacteriuria — no treatment needed","D. Urethritis — Doxycycline for 7 days"]','B','Uncomplicated lower UTI (cystitis) in a non-pregnant woman presents with dysuria, frequency, urgency, and suprapubic pain without systemic features (no fever, no loin pain). First-line treatment per Ghana STG: Nitrofurantoin 100 mg BD for 5-7 days, or Trimethoprim 200 mg BD for 7 days. Ciprofloxacin is a second-line option. Short-course (3-day) therapy is as effective as 7-day courses for uncomplicated cystitis. Pyelonephritis has fever, loin pain, and systemic features and requires longer treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','easy','mcq','Which antibiotic is CONTRAINDICATED for treating urinary tract infections due to poor urinary concentrations and CNS toxicity risk?','["A. Norfloxacin", "B. Trimethoprim", "C. Nitrofurantoin", "D. Ampicillin (no resistance caveat)"]','C','This question has a nuance — Nitrofurantoin is actually a good choice for lower UTI but is CONTRAINDICATED in upper UTI/pyelonephritis because it achieves insufficient tissue concentrations (only concentrated in urine). Additionally, Nitrofurantoin is contraindicated in the last trimester of pregnancy (risk of haemolytic anaemia in the neonate) and in patients with eGFR <30 mL/min. For pyelonephritis, systemic antibiotics like ciprofloxacin, co-amoxiclav, or cephalosporins achieving tissue levels are required.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','mcq','A 30-year-old pregnant woman at 20 weeks gestation is found to have significant bacteriuria (>10^5 CFU/ml of E. coli) on routine urine culture but has NO urinary symptoms. What is the appropriate management?','["A. No treatment \u2014 asymptomatic bacteriuria in pregnancy does not require antibiotics", "B. Treat only if she develops symptoms", "C. Repeat urine culture in 4 weeks before treating", "D. Treat with antibiotics (Nitrofurantoin or Cephalexin) for 7 days to prevent pyelonephritis and preterm labour"]','D','Asymptomatic bacteriuria (ASB) is unique in pregnancy — it MUST be treated because it progresses to pyelonephritis in 25-30% of untreated pregnant women and is associated with preterm labour, low birth weight, and maternal sepsis. All pregnant women should be screened for ASB with urine culture at booking. Treatment: Cephalexin 500 mg QID for 7 days, or Nitrofurantoin 100 mg BD for 7 days (avoid in first trimester and near term). ASB in non-pregnant adults does NOT require treatment (except before urological procedures).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','mcq','A 45-year-old man presents with fever (38.8°C), rigors, right loin pain, dysuria, and frequency. Urinalysis shows pyuria and bacteriuria. Which diagnosis and treatment is appropriate?','["A. Acute pyelonephritis \u2014 Ciprofloxacin 500 mg BD orally for 10-14 days or IV antibiotics if severely ill", "B. Uncomplicated cystitis \u2014 3-day Trimethoprim", "C. Prostatitis \u2014 Doxycycline for 14 days", "D. Renal calculi with secondary infection \u2014 IV morphine only"]','A','Acute pyelonephritis presents with: loin pain/costovertebral angle tenderness, fever, rigors, and lower urinary symptoms (dysuria, frequency). It requires longer antibiotic treatment than cystitis. Ciprofloxacin 500 mg BD for 10-14 days is first-line for outpatient pyelonephritis. Severely ill patients (vomiting, sepsis) need IV antibiotics: Ceftriaxone 1-2 g IV daily or IV Ciprofloxacin, then switched to oral when clinically improved. Note: UTI in men is considered complicated and requires 7-14 days treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','mcq','A catheterised ICU patient develops fever and cloudy, foul-smelling urine. Urine culture grows Pseudomonas aeruginosa >10^5 CFU/mL. Which antibiotic would be most appropriate?','["A. Nitrofurantoin 100 mg BD", "B. Piperacillin-Tazobactam or Ceftazidime IV", "C. Trimethoprim 200 mg BD", "D. Amoxicillin IV"]','B','Catheter-associated UTI (CAUTI) with Pseudomonas aeruginosa requires antibiotics active against Gram-negative non-fermenters: antipseudomonal penicillins (Piperacillin-Tazobactam), antipseudomonal cephalosporins (Ceftazidime, Cefepime), carbapenems (Meropenem for MDR), or aminoglycosides. Nitrofurantoin and Trimethoprim have no activity against Pseudomonas. Amoxicillin is also inactive. The catheter should be removed or changed if possible. Treatment duration: 7 days if responding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','mcq','A 65-year-old man presents with severe perineal pain, fever, dysuria, difficulty urinating, and a boggy tender prostate on digital rectal examination. What is the diagnosis and treatment?','["A. Benign prostatic hyperplasia \u2014 alpha-blockers", "B. Prostate cancer \u2014 urgent urology referral", "C. Acute bacterial prostatitis \u2014 IV antibiotics (Ciprofloxacin or Ceftriaxone) for 4-6 weeks total", "D. Chronic prostatitis \u2014 alpha-blockers only"]','C','Acute bacterial prostatitis presents with: fever, rigors, perineal/pelvic pain, lower urinary symptoms, and an exquisitely tender, hot, boggy prostate on DRE (vigorous massage is contraindicated due to risk of bacteraemia and sepsis). Most common organisms: E. coli, Klebsiella, Pseudomonas. Treatment: fluoroquinolones (Ciprofloxacin) or Trimethoprim-Sulfamethoxazole for 4-6 weeks (for good prostate penetration). Severely ill patients require IV antibiotics initially. Alpha-blockers can help urinary obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','medium','mcq','Which of the following is a complication of ascending UTI that requires immediate surgical or radiological intervention?','["A. Microscopic haematuria", "B. Urine culture growing >10^5 organisms/mL", "C. Pyuria on urinalysis", "D. Perinephric abscess or emphysematous pyelonephritis"]','D','Perinephric abscess (collection of pus in the perirenal fat) and emphysematous pyelonephritis (gas-producing infection of the renal parenchyma, associated with diabetes) are life-threatening complications of ascending UTI. CT of the abdomen is diagnostic. Management: IV antibiotics AND percutaneous drainage or nephrectomy for emphysematous pyelonephritis. Diabetic patients are particularly susceptible. Mortality of emphysematous pyelonephritis is high without nephrectomy in bilateral disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','hard','mcq','A 5-year-old girl has her third UTI in 12 months, each caused by E. coli. She is afebrile between episodes but has mild urinary incontinence. Which investigation should be prioritised to identify a structural cause?','["A. Renal ultrasound and Micturating Cystourethrogram (MCUG) to exclude vesico-ureteric reflux (VUR)", "B. Urine culture during asymptomatic period", "C. CT abdomen with contrast", "D. Cystoscopy under general anaesthesia"]','A','Recurrent UTIs in girls, especially young children, should be investigated for structural abnormalities, particularly vesico-ureteric reflux (VUR) — where urine refluxes from the bladder into the ureter/renal pelvis during micturition. VUR predisposes to recurrent pyelonephritis and renal scarring. Investigation: renal ultrasound (first line, non-invasive) and MCUG (gold standard for VUR diagnosis and grading). Long-term prophylactic antibiotics (Nitrofurantoin or Trimethoprim) are used for VUR grade III-V pending surgical or endoscopic correction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Urinary Tract Infections','hard','mcq','A woman presents with her fourth episode of cystitis in 12 months, each culture-confirmed. She is not pregnant, has no structural abnormality, and remains well between episodes. What management strategy is recommended?','["A. Immediate cystoscopy to exclude bladder pathology", "B. Long-term prophylactic antibiotics (e.g., Nitrofurantoin 100 mg nightly) or post-coital prophylaxis", "C. No further intervention \u2014 recurrent cystitis is harmless", "D. Long-term ciprofloxacin at full therapeutic dose indefinitely"]','B','Recurrent UTIs (≥2 episodes in 6 months or ≥3 in 12 months) in non-pregnant women without structural abnormality are managed with: low-dose continuous prophylaxis (Nitrofurantoin 50-100 mg nightly or Trimethoprim 100 mg nightly for 6-12 months), or patient-initiated self-start therapy, or post-coital prophylaxis (if related to intercourse). Behavioural modifications: adequate hydration, voiding after intercourse. Long-term full-dose ciprofloxacin risks resistance development. Recurrent cystitis does not progress to renal damage in women without VUR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','mcq','According to Ghana STG 2017, what is the first-line treatment for uncomplicated gonococcal infection (urethritis/cervicitis)?','["A. Ceftriaxone 250 mg IM stat plus Azithromycin 1 g oral stat", "B. Penicillin V oral 500 mg QID for 7 days", "C. Ciprofloxacin 500 mg oral single dose", "D. Doxycycline 100 mg BD for 14 days alone"]','A','The Ghana STG 2017 recommends Ceftriaxone 250 mg IM as a single dose PLUS Azithromycin 1 g oral single dose for uncomplicated gonorrhoea (dual therapy). Dual therapy is essential because: (1) Neisseria gonorrhoeae has widespread fluoroquinolone resistance making ciprofloxacin unreliable; (2) co-infection with Chlamydia trachomatis occurs in 20-40% of cases; (3) Azithromycin also targets Chlamydia. Penicillin resistance is also widespread. Treat partner concurrently.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','mcq','What is the recommended treatment for early syphilis (primary and secondary) according to Ghana STG 2017?','["A. Doxycycline 100 mg BD for 14 days","B. Benzathine Benzylpenicillin 2.4 million units IM as a single dose","C. Azithromycin 2 g oral single dose","D. Ceftriaxone 1 g IM daily for 10 days"]','B','Benzathine Benzylpenicillin (long-acting penicillin) 2.4 MU IM as a single dose is the treatment of choice for early syphilis (primary, secondary, and early latent). For late latent syphilis or syphilis of unknown duration: 2.4 MU IM once weekly for 3 consecutive weeks. Neurosyphilis requires IV Benzylpenicillin 18-24 MU/day for 10-14 days. Penicillin allergy: Doxycycline 100 mg BD for 14 days is an alternative (but not in pregnancy — desensitise and use penicillin).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','easy','mcq','A 25-year-old woman presents with a painless, indurated, clean-based genital ulcer. Inguinal lymphadenopathy is present but non-tender. Which diagnosis is most likely?','["A. Genital herpes \u2014 multiple painful vesicles/ulcers", "B. Chancroid (Haemophilus ducreyi) \u2014 painful soft ulcer", "C. Syphilis (Treponema pallidum) \u2014 painless chancre of primary syphilis", "D. Lymphogranuloma venereum \u2014 small painless ulcer with painful inguinal bubo"]','C','The painless, indurated (hard-based), clean genital ulcer with non-tender inguinal lymphadenopathy is the classic primary chancre of syphilis (Treponema pallidum). The chancre heals spontaneously in 3-6 weeks even without treatment, but the infection progresses. Key differential: Herpes simplex causes painful vesicles/ulcers; Chancroid (H. ducreyi) causes painful soft necrotic ulcers; LGV causes a small transient ulcer with marked painful inguinal lymphadenopathy (bubo). Diagnostic test: darkfield microscopy of chancre exudate, or TPHA/VDRL serology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','mcq','A patient with secondary syphilis is treated with Benzathine Benzylpenicillin. Within 12 hours they develop fever, rigors, headache, and flushing. What is this reaction and how should it be managed?','["A. Penicillin allergy \u2014 stop treatment and use doxycycline", "B. Treatment failure \u2014 increase penicillin dose", "C. Serum sickness \u2014 use antihistamines and reduce dose", "D. Jarisch-Herxheimer reaction \u2014 reassure patient, use paracetamol; continue penicillin"]','D','The Jarisch-Herxheimer reaction occurs within 2-12 hours of treatment for spirochaetal infections (syphilis, Lyme disease, leptospirosis, relapsing fever). It is caused by massive cytokine release (TNF-alpha, IL-6, IL-8) following rapid killing of spirochaetes. Features: fever, rigors, headache, myalgia, worsening rash. Management: reassurance, antipyretics (paracetamol), and continuation of antibiotic therapy. Prednisolone may be given before treatment in severe cases or in pregnancy (prevents premature labour from the reaction). This is NOT an allergy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','mcq','A 22-year-old woman presents with vaginal discharge, lower abdominal pain, and cervical motion tenderness (chandelier sign) on bimanual examination. Which diagnosis and treatment is indicated?','["A. Pelvic Inflammatory Disease (PID) \u2014 Ceftriaxone IM plus Doxycycline plus Metronidazole", "B. Bacterial vaginosis \u2014 Metronidazole 400 mg BD for 7 days", "C. Candidal vaginitis \u2014 Clotrimazole pessary", "D. Trichomoniasis \u2014 Metronidazole 2 g single dose"]','A','Pelvic Inflammatory Disease (PID) is an ascending infection of the upper genital tract (endometritis, salpingitis, peritonitis) caused by N. gonorrhoeae, C. trachomatis, and anaerobes. Cervical motion tenderness (chandelier sign) is pathognomonic. Treatment covers all three: Ceftriaxone 500 mg IM stat (for gonorrhoea) PLUS Doxycycline 100 mg BD for 14 days (for Chlamydia) PLUS Metronidazole 400 mg BD for 14 days (for anaerobes). Hospitalisation for severe PID, pregnancy, failed outpatient therapy, or pelvic abscess.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','mcq','A 30-year-old presents with multiple painful genital blisters/vesicles for 3 days, preceded by tingling and burning. This is a recurrence of a previous similar episode. Which treatment is recommended?','["A. Benzathine Benzylpenicillin IM stat — this is syphilis","B. Aciclovir 400 mg three times daily for 5 days or Valaciclovir 500 mg BD for 5 days","C. Ciprofloxacin 500 mg stat — this is chancroid","D. Doxycycline 100 mg BD for 14 days — this is LGV"]','B','Genital herpes (HSV-2 predominantly, also HSV-1) causes recurrent painful vesicular eruptions. First episode: Aciclovir 200 mg five times daily for 10 days, or 400 mg TID for 7-10 days. Recurrences: Aciclovir 400 mg TID or 800 mg BD for 5 days (shorter course sufficient). Suppressive therapy for frequent recurrences (≥6/year): Aciclovir 400 mg BD or Valaciclovir 500 mg daily. Aciclovir does not cure herpes but reduces severity and duration. Partner notification is important.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','mcq','What is the recommended treatment for genital warts (condylomata acuminata) caused by Human Papillomavirus (HPV)?','["A. Aciclovir cream topically", "B. Benzathine Benzylpenicillin IM", "C. Podophyllotoxin 0.5% solution or Imiquimod 5% cream topically, or ablative therapies", "D. Oral Doxycycline for 14 days"]','C','Genital warts (condylomata acuminata) are caused by HPV types 6 and 11 (low-risk, non-oncogenic). Treatment options: patient-applied (Podophyllotoxin 0.5% BD for 3 days per week up to 4 cycles; Imiquimod 5% cream three times weekly for up to 16 weeks) or provider-applied ablative treatments (cryotherapy, electrosurgery, surgical excision, or trichloroacetic acid 80-90%). HPV types 16 and 18 cause cervical cancer. HPV vaccination (Cervarix, Gardasil) prevents infection. Aciclovir has no activity against HPV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','medium','mcq','A pregnant woman at 32 weeks gestation is found to have active syphilis (TPHA positive, VDRL titre 1:16). She reports penicillin allergy (rash). What is the most appropriate management?','["A. Doxycycline 100 mg BD for 14 days \u2014 safe in pregnancy", "B. Azithromycin 2 g single oral dose \u2014 reliable alternative", "C. Defer treatment until after delivery", "D. Penicillin desensitisation followed by Benzathine Benzylpenicillin treatment"]','D','Penicillin is the ONLY treatment proven to be safe and effective for syphilis in pregnancy, preventing congenital syphilis. Doxycycline is contraindicated in pregnancy (fetal tooth discolouration, skeletal abnormalities). Azithromycin is unreliable due to macrolide resistance in Treponema pallidum. Therefore, pregnant women with penicillin allergy MUST undergo penicillin desensitisation (in a supervised hospital setting) and then receive Benzathine Benzylpenicillin. Deferring treatment risks congenital syphilis, stillbirth, and neonatal death.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','hard','mcq','A 35-year-old man presents with urethral discharge for 5 days. Gram stain of the discharge shows intracellular Gram-negative diplococci. He is treated with ceftriaxone plus azithromycin. Three weeks later, symptoms recur. NAAT testing shows Chlamydia trachomatis positive. What was the most likely cause of the initial treatment failure and subsequent positive NAAT?','["A. Concurrent Chlamydia infection not adequately treated, or re-infection from untreated partner", "B. Ceftriaxone resistance in Neisseria gonorrhoeae", "C. Azithromycin resistance in Treponema pallidum", "D. The NAAT is a false positive after treatment"]','A','Chlamydia trachomatis co-infects 20-40% of patients with gonorrhoea. While the initial dual therapy (ceftriaxone + azithromycin) covers both, azithromycin 1 g as a single dose may provide suboptimal treatment for Chlamydia compared to a 7-day doxycycline course. Additionally, recurrence 3 weeks later suggests either: incomplete Chlamydia eradication (azithromycin single dose has higher treatment failure for Chlamydia than 7-day doxycycline) or re-infection from an untreated partner. Partner notification and testing is essential. NAAT remains positive for 3-5 weeks after successful treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Sexually Transmitted Infections','hard','mcq','A 28-year-old HIV-positive man presents with neurosyphilis (headache, altered vision, meningism, CSF VDRL reactive). Which treatment is appropriate?','["A. Benzathine Benzylpenicillin 2.4 MU IM once weekly for 3 weeks","B. IV Benzylpenicillin 3-4 million units every 4 hours for 10-14 days","C. Doxycycline 200 mg BD for 28 days","D. Ceftriaxone 2 g IV once daily for 14 days as the sole treatment"]','B','Neurosyphilis requires IV Benzylpenicillin (aqueous crystalline penicillin G) 18-24 million units/day (3-4 MU every 4 hours) for 10-14 days to achieve treponemicidal CSF concentrations. Benzathine Penicillin does NOT achieve adequate CSF concentrations and cannot be used for neurosyphilis. Alternative: Ceftriaxone 2 g IV daily for 10-14 days (some evidence, used if IV penicillin is unavailable). HIV patients with syphilis have higher rates of neurosyphilis and treatment failure; close follow-up with repeat CSF examination at 6 months is required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','mcq','What is the classic clinical triad of bacterial meningitis?','["A. Fever, neck stiffness, and altered consciousness (headache is often included)", "B. Fever, rash, and hypotension", "C. Headache, vomiting, and papilloedema", "D. Seizures, focal neurological deficit, and fever"]','A','The classic triad of bacterial meningitis is: fever, neck stiffness (meningism/nuchal rigidity), and altered consciousness (or headache). Additional features: photophobia, phonophobia, positive Kernig''s sign (inability to extend the knee when hip is flexed 90°), positive Brudzinski''s sign (flexion of the neck causes reflexive hip and knee flexion). Petechial/purpuric rash suggests meningococcal disease. Not all three elements of the triad are present in every case; altered consciousness may be absent in early disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','mcq','According to Ghana STG 2017, what is the first-line empirical treatment for bacterial meningitis in adults aged under 50 years?','["A. Ampicillin plus Gentamicin IV","B. Ceftriaxone IV plus Vancomycin IV","C. Benzylpenicillin IV alone","D. Chloramphenicol IV alone"]','B','Per Ghana STG 2017 (Table 18-13), the first-line empirical treatment for bacterial meningitis in adults <50 years (targeting Meningococcus, Pneumococcus, H. influenzae) is: Ceftriaxone IV (50-80 mg/kg, max 4 g/day for adults) PLUS Vancomycin IV (15 mg/kg 12 hourly for 7-10 days). Ceftriaxone covers the common pathogens; Vancomycin is added for penicillin/cephalosporin-resistant pneumococcus. Benzylpenicillin plus Chloramphenicol is an alternative (Evidence B). In >50 years: Ceftriaxone OR Ampicillin (covers Listeria) plus Vancomycin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','easy','mcq','Which organism is responsible for epidemic meningitis in the "meningitis belt" of sub-Saharan Africa (including Northern Ghana) during the harmattan season?','["A. Streptococcus pneumoniae", "B. Haemophilus influenzae type b", "C. Neisseria meningitidis (meningococcus)", "D. Listeria monocytogenes"]','C','Neisseria meningitidis (meningococcus) causes epidemic meningitis in the African "meningitis belt" — a region extending from Senegal to Ethiopia, including Northern and Upper Regions of Ghana. Epidemics occur during the dry harmattan season (December-June) when dust and cold air damage the mucous membranes, facilitating spread. The Ghana STG specifically mentions Cerebrospinal Meningitis (CSM) due to N. meningitidis occurring in epidemics in Northern and Upper Regions. Serogroup A, C, W, and X predominate in Africa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','mcq','Before performing a lumbar puncture in a suspected meningitis patient, when is a CT head scan required first?','["A. CT head is always required before LP in all patients", "B. CT head is never needed before LP if the diagnosis is clear", "C. CT head is only needed if the patient is unconscious", "D. CT head should be done first if there are signs of raised intracranial pressure, focal neurological signs, papilloedema, or recent seizures"]','D','A CT head scan should be performed BEFORE lumbar puncture if any of the following are present: papilloedema, focal neurological deficits, altered consciousness (GCS <13), recent seizures (within 1 week), or immunocompromised state. These suggest raised ICP, and LP could cause cerebral herniation ("coning"). However, LP should NOT be delayed >1 hour from hospital arrival — antibiotics should be given IMMEDIATELY if meningitis is suspected, even before LP or CT. Do not delay antibiotics waiting for investigations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','mcq','Which CSF findings distinguish bacterial meningitis from viral meningitis?','["A. Bacterial: turbid fluid, very low glucose (<45% serum), very high protein (>1 g/L), neutrophil pleocytosis; Viral: clear fluid, normal/slightly low glucose, moderate protein, lymphocytic pleocytosis", "B. Bacterial: clear fluid, normal glucose, elevated protein; Viral: turbid fluid, low glucose, very high protein", "C. Both conditions show identical CSF findings", "D. Bacterial: high glucose; Viral: very low glucose"]','A','CSF findings: Bacterial meningitis: turbid/purulent, opening pressure elevated, WBC 1000-10,000 cells/µL (predominantly neutrophils), protein >1 g/L (often >2 g/L), glucose <45% of serum glucose (often <1 mmol/L). Viral meningitis (aseptic): clear, WBC 10-300 cells/µL (predominantly lymphocytes), protein mildly elevated (0.5-1 g/L), glucose normal. TB meningitis: clear/xanthochromic, lymphocytic pleocytosis, very low glucose, elevated protein, with AFB smear (low sensitivity). Knowing CSF interpretation is high-yield.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','mcq','A 20-year-old student develops sudden-onset severe headache ("thunderclap"), neck stiffness, and photophobia. CT head is normal. LP shows xanthochromia (yellow CSF) with no white cells. What is the most likely diagnosis?','["A. Bacterial meningitis","B. Subarachnoid haemorrhage (SAH)","C. Viral meningitis","D. TB meningitis"]','B','Xanthochromia (yellow discolouration of CSF due to bilirubin from degraded blood) with no pleocytosis (no white cells) is the hallmark of subarachnoid haemorrhage (SAH), not meningitis. SAH presents with sudden-onset "thunderclap" headache ("worst headache of my life"), neck stiffness, photophobia, and nausea. CT head detects ~95% of SAH within 12 hours but may be normal (especially after 6-12 hours). LP demonstrating xanthochromia (spectrophotometry is more sensitive than visual inspection) confirms the diagnosis. SAH requires urgent neurosurgical referral.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','mcq','Dexamethasone is recommended as adjunctive therapy in bacterial meningitis. In which specific population is it most clearly beneficial in reducing mortality and neurological sequelae?','["A. All patients with suspected meningitis regardless of cause", "B. Meningococcal meningitis only", "C. Pneumococcal meningitis in adults \u2014 given 15-20 minutes before or with the first dose of antibiotics", "D. Neonatal meningitis"]','C','Adjunctive Dexamethasone (0.15 mg/kg QID for 4 days) is most beneficial in adults with suspected pneumococcal meningitis, given 15-20 minutes before or with the first antibiotic dose to reduce cytokine-mediated inflammation. It significantly reduces hearing loss and neurological sequelae in adults with pneumococcal meningitis in high-income settings. Evidence is less clear for meningococcal meningitis or paediatric meningitis in resource-limited settings. Some guidelines recommend dexamethasone for all suspected bacterial meningitis in adults pending pathogen identification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','medium','mcq','A 30-year-old presents with fever, confusion, and focal seizures for 3 days. MRI brain shows temporal lobe enhancement. CSF shows lymphocytic pleocytosis and elevated protein. Which diagnosis is most likely and what is the emergency treatment?','["A. Bacterial meningitis \u2014 IV Ceftriaxone", "B. Tuberculous meningitis \u2014 4-drug anti-TB treatment", "C. Cerebral malaria \u2014 IV Artesunate", "D. Herpes Simplex Encephalitis \u2014 IV Aciclovir 10 mg/kg 8 hourly"]','D','Herpes Simplex Encephalitis (HSE, caused by HSV-1) is the most common fatal sporadic encephalitis. Classic features: fever, headache, altered consciousness, focal seizures, and temporal lobe involvement on MRI (haemorrhagic necrosis). CSF: lymphocytic pleocytosis, elevated protein, normal glucose, HSV PCR positive. Treatment: IV Aciclovir 10 mg/kg 8 hourly for 14-21 days. Treatment must be started empirically before HSV PCR results, as delayed treatment dramatically worsens prognosis. This is a life-threatening emergency requiring immediate antiviral therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','hard','mcq','TB meningitis is most likely in which clinical scenario and what are the characteristic CSF findings?','["A. HIV-positive patient with subacute meningism, CSF lymphocytosis, very low glucose, elevated protein, with AFB on Ziehl-Neelsen stain or Xpert MTB/RIF positive", "B. Young child with acute onset of high fever and turbid CSF with >10,000 neutrophils", "C. Adult with rapid progression to coma within 24 hours and petechial rash", "D. Elderly patient with hospital-acquired infection and gram-negative bacilli in CSF"]','A','TB meningitis (TBM) presents subacutely (weeks) in immunocompromised patients (HIV, malnourished, infants). CSF: clear or xanthochromic, lymphocytic pleocytosis (100-500 cells/µL), very low glucose (<2.5 mmol/L, CSF:serum ratio <0.5), elevated protein (1-5 g/L), with fibrin pellicle. ZN smear is only 10-40% sensitive; Xpert MTB/RIF on CSF has better sensitivity (~80%). Treatment: 2RHZE/10RH (12 months total) plus Dexamethasone 0.4 mg/kg/day tapering over 6 weeks reduces mortality significantly. ART is delayed 4-8 weeks in TB/HIV meningitis co-infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Meningitis & Encephalitis','hard','mcq','A 45-year-old returning from rural West Africa develops fever, headache, and behavioural changes 10 days after multiple tsetse fly bites. Peripheral blood smear and CSF show trypanosomes. What is this condition and its treatment?','["A. Malaria — IV Artesunate","B. West African Sleeping Sickness (Trypanosoma brucei gambiense) — Pentamidine for stage 1, Eflornithine or NECT (Nifurtimox-Eflornithine) for stage 2 (CNS involvement)","C. Leishmaniasis — Liposomal Amphotericin B","D. Schistosomiasis — Praziquantel"]','B','African Trypanosomiasis (sleeping sickness) is caused by Trypanosoma brucei gambiense (West Africa, slower progression) or T. b. rhodesiense (East Africa, rapid). Stage 1 (haemolymphatic): fever, Winterbottom''s sign (posterior cervical lymphadenopathy). Stage 2 (meningo-encephalitic): CNS involvement, sleep disturbance, behavioural changes. Diagnosis: blood/lymph node/CSF smear showing trypanosomes. Treatment: Stage 1 (West African): Pentamidine IM or Fexinidazole oral (newer). Stage 2: Eflornithine IV or NECT combination. Ghana is in the West African endemic zone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','mcq','What are the two most common bacteria causing cellulitis and impetigo?','["A. Streptococcus pyogenes (Group A Streptococcus) and Staphylococcus aureus", "B. Pseudomonas aeruginosa and E. coli", "C. Clostridium perfringens and Bacteroides fragilis", "D. Haemophilus influenzae and Streptococcus pneumoniae"]','A','Streptococcus pyogenes (Group A beta-haemolytic Streptococcus, GAS) and Staphylococcus aureus are the leading causes of common skin and soft tissue infections: impetigo, cellulitis, folliculitis, furuncles, and carbuncles. GAS tends to cause spreading non-purulent cellulitis and erysipelas. S. aureus causes purulent infections (abscesses, furuncles). Methicillin-resistant S. aureus (MRSA) is increasingly common. Knowledge of these causative organisms guides empirical antibiotic choice.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','mcq','A 10-year-old child presents with honey-coloured crusting lesions around the mouth and nose. Which diagnosis and treatment is appropriate?','["A. Tinea faciei — antifungal cream","B. Impetigo — Mupirocin topical cream or Cloxacillin oral for extensive disease","C. Herpes simplex — Aciclovir cream","D. Eczema — hydrocortisone cream"]','B','Impetigo is a superficial bacterial skin infection caused by S. aureus and/or GAS. Classic presentation: golden/honey-coloured crusted lesions on the face (especially around mouth and nose) in children. Non-bullous impetigo is most common. Treatment: Limited disease — Mupirocin 2% ointment or Fusidic acid cream topically for 5-7 days. Extensive disease — Flucloxacillin or Cloxacillin 500 mg QID for 7 days (covers S. aureus). Amoxicillin-Clavulanate is an alternative. Hygiene measures prevent spread in schools and households.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','easy','mcq','A 40-year-old woman presents with a rapidly spreading, well-demarcated, bright-red, raised, warm, tender lesion on the face with clear margin from normal skin. She has fever and chills. Which condition is this?','["A. Cellulitis", "B. Necrotising fasciitis", "C. Erysipelas", "D. Infected eczema"]','C','Erysipelas is a superficial dermal infection (involving lymphatics) caused almost exclusively by Group A Streptococcus. Key features: well-demarcated, raised, bright red "butterfly" lesion (especially face), clear margin between infected and normal skin (distinguishes it from deeper cellulitis, which has indistinct margins), rapid spread, and systemic features (fever, rigors). Treatment: Penicillin V oral (mild) or IV Benzylpenicillin (severe). Cellulitis is deeper (dermis and subcutaneous tissue) with indistinct borders and is usually caused by S. aureus or GAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','mcq','A diabetic patient presents with a tender, fluctuant swelling in the axilla with central pustule. This is a furuncle (boil). What is the most appropriate management?','["A. Oral antibiotics alone for 14 days", "B. IV antibiotics without drainage", "C. Oral antihistamines and topical corticosteroids", "D. Incision and drainage (I&D) \u2014 the primary treatment; antibiotics only if there is surrounding cellulitis, systemic features, or recurrence"]','D','Furuncles (boils) and carbuncles (clusters of furuncles) are caused by S. aureus. Primary treatment is Incision and Drainage (I&D) — antibiotics alone without drainage are inadequate because the abscess cavity is avascular and poorly penetrated by antibiotics. Antibiotics are added for: surrounding cellulitis, systemic features (fever), immunocompromised patients, or recurrent infections. If MRSA is suspected: Trimethoprim-Sulfamethoxazole or Doxycycline. Culture and sensitivity should guide therapy in recurrent cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','mcq','A 55-year-old diabetic man presents with severe pain in his right lower leg, disproportionate to the skin appearance, with a dusky discoloured skin, crepitus on palpation, and rapid deterioration. What is the diagnosis and most critical intervention?','["A. Necrotising fasciitis \u2014 emergency surgical debridement plus broad-spectrum IV antibiotics", "B. Severe cellulitis \u2014 IV antibiotics for 2 weeks", "C. Deep vein thrombosis \u2014 anticoagulation", "D. Compartment syndrome \u2014 fasciotomy only"]','A','Necrotising fasciitis (NF) is a life-threatening, rapidly spreading infection of the fascia and subcutaneous tissue. Key features: severe pain disproportionate to skin appearance, skin necrosis/discolouration, gas in tissues (crepitus), and rapid systemic deterioration (septic shock). The "finger test" (easy tissue plane dissection with a finger in the operating room) confirms the diagnosis. Management: EMERGENCY surgical debridement (removing all necrotic tissue) is the cornerstone — without surgery, mortality approaches 100%. Broad-spectrum IV antibiotics (Piperacillin-Tazobactam + Clindamycin + Vancomycin). ICU support.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','mcq','A 12-year-old presents with intensely itchy, linear burrows between fingers, on the wrists, and around the umbilicus. Other family members are similarly affected. What is the diagnosis and treatment?','["A. Tinea corporis — Clotrimazole cream","B. Scabies — Permethrin 5% cream applied overnight or Benzyl Benzoate 25% lotion","C. Atopic eczema — emollients and topical steroids","D. Chickenpox — Aciclovir"]','B','Scabies is caused by Sarcoptes scabiei mite infestation. Features: intensely pruritic (especially at night), linear burrows, and a distribution favouring web spaces of fingers, wrists, umbilicus, genitalia, and axillae (sparing face in adults). Multiple household members affected. Treatment: Permethrin 5% cream (first-line, applied to all skin from neck down, washed off after 8-12 hours, repeated after 7 days) or Benzyl Benzoate 25% (applied for 24 hours, 2-3 applications). All household contacts must be treated simultaneously. Clothing and bedding should be washed. Oral Ivermectin is effective for crusted/Norwegian scabies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','mcq','A 35-year-old patient develops a large fluctuant swelling in the perianal region with severe pain, fever, and inability to sit. What is the diagnosis and management?','["A. Haemorrhoids \u2014 topical treatment", "B. Pilonidal cyst \u2014 conservative management", "C. Perianal abscess \u2014 incision and drainage under anaesthesia plus antibiotics for extensive disease", "D. Anal fissure \u2014 topical GTN cream"]','C','Perianal abscess results from infection of anal glands at the dentate line, caused by a mixed flora of gut organisms (E. coli, Bacteroides, Enterococcus). Features: severe throbbing perianal pain, fever, and a fluctuant tender swelling near the anus. Management: prompt incision and drainage (I&D) under anaesthesia is curative — antibiotics alone are insufficient. Post-drainage, examine for an underlying fistula-in-ano. Antibiotics (Metronidazole + Ciprofloxacin) are added if there is surrounding cellulitis, systemic features, or immunocompromise. About 30-50% develop a fistula requiring surgical management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','medium','mcq','Which organism causes "Buruli ulcer", an important neglected tropical skin disease endemic in parts of Ghana?','["A. Mycobacterium tuberculosis", "B. Leishmania major", "C. Treponema pallidum", "D. Mycobacterium ulcerans"]','D','Buruli ulcer is caused by Mycobacterium ulcerans, which produces mycolactone — a toxin causing massive painless tissue necrosis. Ghana has one of the highest burdens globally, particularly in Ashanti, Eastern, and Central Regions near slow-moving water. Features: initially painless nodule/plaque/oedema progressing to a large painless ulcer with undermined edges and a necrotic base. Treatment: Rifampicin 10 mg/kg/day + Clarithromycin 7.5 mg/kg BD (or Streptomycin + Rifampicin) for 8 weeks. Surgery may be needed for large lesions. The Ghana NTP has a specific Buruli Ulcer Control Programme.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','hard','mcq','A 25-year-old patient presents with a painless papule on the forearm that develops into an ulcer with a black eschar. They work as a livestock farmer. Blood culture grows large Gram-positive rods. What is the diagnosis and treatment?','["A. Cutaneous anthrax (Bacillus anthracis) \u2014 Ciprofloxacin 500 mg BD for 60 days (or Doxycycline 100 mg BD)", "B. Staphylococcal skin infection \u2014 Flucloxacillin", "C. Leprosy \u2014 Rifampicin, Dapsone, Clofazimine", "D. Cutaneous leishmaniasis \u2014 Sodium stibogluconate"]','A','Cutaneous anthrax (Bacillus anthracis) presents as a painless papule progressing to an ulcer with a characteristic black eschar (necrotic crust) and surrounding non-pitting oedema. It occurs through skin contact with contaminated animals or animal products (hides, wool, meat). Malignant pustule is the classic term. Diagnosis: Gram stain/culture of exudate, blood culture, or PCR. Treatment: Ciprofloxacin 500 mg BD for 60 days (bioterrorism scenarios), or Doxycycline 100 mg BD. Natural cutaneous anthrax: 7-10 days of antibiotics usually sufficient. Anthrax is a notifiable disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Skin & Soft Tissue Infections','hard','mcq','A patient with poorly controlled diabetes develops painful swelling, erythema, and crepitus of the scrotum and perineum with rapidly spreading necrosis. CT shows gas in soft tissues. What is this life-threatening condition?','["A. Epididymo-orchitis — IV Ceftriaxone","B. Fournier''s gangrene (perineal necrotising fasciitis) — emergency surgical debridement plus broad-spectrum antibiotics and ICU care","C. Testicular torsion — emergency orchidopexy","D. Strangulated inguinal hernia — emergency hernia repair"]','B','Fournier''s gangrene is a type of necrotising fasciitis affecting the perineum and genitalia, typically in diabetic, obese, or immunocompromised men. It is a polymicrobial synergistic infection (E. coli, Bacteroides, Streptococcus, Clostridium). Features: rapid onset of perineal pain, swelling, erythema, crepitus (gas in tissues from anaerobic bacteria), and rapidly spreading necrosis with systemic sepsis. This is a surgical emergency with >20% mortality despite treatment. Management: broad-spectrum IV antibiotics (Piperacillin-Tazobactam + Metronidazole + Vancomycin) AND immediate wide surgical debridement of all necrotic tissue. Hyperbaric oxygen is an adjunct if available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','mcq','What is the primary goal of Antimicrobial Stewardship Programmes (ASPs) in hospitals?','["A. To optimise antimicrobial use \u2014 ensuring the right drug, right dose, right duration, and right route \u2014 to improve patient outcomes and reduce antimicrobial resistance", "B. To reduce hospital expenditure on antibiotics only", "C. To restrict antibiotic prescribing to specialists only", "D. To replace antibiotics with probiotics in all infections"]','A','Antimicrobial Stewardship Programmes (ASPs) aim to optimise antimicrobial therapy by promoting: right drug (appropriate spectrum), right dose, right duration, right route, and right timing. Goals: improve clinical outcomes, minimise adverse effects (Clostridioides difficile colitis, organ toxicity), prevent emergence of resistance, and reduce costs. ASPs use strategies including prospective audit with feedback, formulary restriction, antibiotic cycling, and de-escalation protocols. AMR is a global health crisis — WHO estimates 10 million deaths/year attributable to AMR by 2050.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','mcq','Which of the following is a key mechanism by which bacteria develop resistance to beta-lactam antibiotics such as Amoxicillin?','["A. Decreased expression of efflux pumps","B. Production of beta-lactamase enzymes that hydrolyse the beta-lactam ring","C. Increased expression of penicillin-binding proteins","D. Upregulation of folic acid synthesis"]','B','Beta-lactamase production is the most common mechanism of resistance to penicillins and cephalosporins. Beta-lactamase enzymes hydrolyse the beta-lactam ring, rendering the antibiotic inactive. Examples: Staphylococcal penicillinase, Extended-Spectrum Beta-Lactamases (ESBLs) in E. coli and Klebsiella (resistant to most penicillins and cephalosporins). Solutions: beta-lactamase inhibitors (clavulanate, sulbactam, tazobactam); carbapenems resist most beta-lactamases. Other mechanisms: efflux pumps (pump out antibiotic), porin mutations (reduce entry), altered penicillin-binding proteins (MRSA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','easy','mcq','What does Minimum Inhibitory Concentration (MIC) mean in clinical microbiology?','["A. The minimum dose of antibiotic that causes side effects in a patient", "B. The minimum duration of antibiotic treatment needed to cure an infection", "C. The lowest concentration of an antibiotic that inhibits visible bacterial growth in vitro", "D. The concentration of antibiotic in blood that kills 50% of bacteria"]','C','The Minimum Inhibitory Concentration (MIC) is the lowest concentration of an antimicrobial agent that prevents visible in vitro bacterial growth after overnight incubation. It is reported alongside susceptibility categories (Susceptible, Intermediate, Resistant) based on EUCAST or CLSI breakpoints. A lower MIC generally indicates better antibiotic potency against a given organism. MBC (Minimum Bactericidal Concentration) is the lowest concentration that kills 99.9% of bacteria. Understanding MIC is fundamental to interpreting culture and sensitivity reports.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','mcq','A patient is started on empirical broad-spectrum antibiotics (Piperacillin-Tazobactam) for suspected hospital-acquired pneumonia. Blood cultures return after 48 hours showing Streptococcus pneumoniae fully sensitive to Penicillin. What is the most appropriate next step?','["A. Continue Piperacillin-Tazobactam for the full 14-day course", "B. Stop all antibiotics as the patient is improving", "C. Add Vancomycin to the current regimen", "D. De-escalate to IV Benzylpenicillin or oral Amoxicillin (narrowest effective spectrum)"]','D','De-escalation is a cornerstone of antimicrobial stewardship: switching from broad-spectrum empirical antibiotics to the narrowest effective agent once culture and sensitivity results are available. Here, pneumococcus fully sensitive to penicillin should be treated with IV Benzylpenicillin or oral Amoxicillin — narrower spectrum, cheaper, and equally effective. Continuing Piperacillin-Tazobactam unnecessarily promotes resistance, increases cost, and raises the risk of adverse effects (C. difficile colitis). De-escalation should be performed in all patients where culture results allow it.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','mcq','Aminoglycosides (Gentamicin, Amikacin) are important antibiotics with specific toxicity profiles. Which combination of adverse effects is classically associated with aminoglycosides?','["A. Nephrotoxicity and ototoxicity (cochlear and vestibular)", "B. Hepatotoxicity and peripheral neuropathy", "C. Optic neuritis and thrombocytopaenia", "D. QT prolongation and tendon rupture"]','A','Aminoglycosides cause two major dose-dependent toxicities: (1) Nephrotoxicity — proximal tubular cell damage causing acute tubular necrosis, typically after 5-7 days; reversible if detected early. (2) Ototoxicity — cochlear (sensorineural hearing loss, irreversible) and vestibular (tinnitus, vertigo). Risk factors: prolonged use, high doses, elderly, pre-existing renal impairment, concurrent nephrotoxic drugs. Monitoring: once-daily dosing reduces nephrotoxicity; serum drug levels (peak and trough for BD/TID dosing); daily serum creatinine; and audiological monitoring for prolonged use.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','mcq','Fluoroquinolones (Ciprofloxacin, Levofloxacin) are broad-spectrum antibiotics with important side effects and drug interactions. Which serious adverse effect is associated with fluoroquinolone use?','["A. Irreversible hepatotoxicity in all patients","B. QT interval prolongation, tendon rupture (especially Achilles), and peripheral neuropathy","C. Haemolytic anaemia in G6PD deficiency","D. Pulmonary toxicity and interstitial fibrosis"]','B','Fluoroquinolones have several important adverse effects: (1) QT prolongation — risk of torsades de pointes, especially with other QT-prolonging drugs; (2) Tendon rupture — especially Achilles tendon, particularly in patients >60 years, with corticosteroid use, or with renal failure; (3) Peripheral neuropathy (rare but may be irreversible); (4) CNS effects: seizures, confusion (especially in elderly); (5) Cartilage damage (contraindicated in children and pregnancy). The FDA has issued Black Box warnings for tendinitis/tendon rupture and peripheral neuropathy. Fluoroquinolones are also being restricted to preserve efficacy against serious infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','mcq','Which class of antibiotics acts by inhibiting bacterial cell wall synthesis by binding to penicillin-binding proteins (PBPs) and blocking peptidoglycan cross-linking?','["A. Macrolides (Azithromycin, Erythromycin)", "B. Tetracyclines (Doxycycline)", "C. Beta-lactams (Penicillins, Cephalosporins, Carbapenems, Monobactams)", "D. Fluoroquinolones (Ciprofloxacin)"]','C','Beta-lactam antibiotics (penicillins, cephalosporins, carbapenems, monobactams) inhibit bacterial cell wall synthesis by irreversibly binding to Penicillin-Binding Proteins (PBPs), which are transpeptidases responsible for cross-linking peptidoglycan chains in the bacterial cell wall. Without a functional cell wall, bacteria lyse due to osmotic pressure. Beta-lactams are bactericidal and time-dependent (efficacy depends on time above MIC). Macrolides inhibit 50S ribosome (protein synthesis). Tetracyclines inhibit 30S ribosome. Fluoroquinolones inhibit DNA gyrase/topoisomerase IV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','medium','mcq','A patient presents to the outpatient clinic with a 3-day history of common cold (clear nasal discharge, mild sore throat, no fever, no purulent discharge). The patient requests antibiotics. What is the most appropriate response?','["A. Prescribe Amoxicillin to prevent secondary bacterial infection", "B. Order throat swab culture before deciding", "C. Prescribe Azithromycin as it also has anti-inflammatory effects", "D. Explain that the common cold is viral; antibiotics are not indicated and worsen antimicrobial resistance. Treat symptomatically."]','D','The common cold is caused by rhinovirus (most commonly), coronavirus, RSV, adenovirus, and others — all VIRAL. Antibiotics have no effect on viral infections and should NOT be prescribed for: common cold, uncomplicated acute bronchitis, most sore throats (>90% are viral), and uncomplicated sinusitis <10 days. Prescribing antibiotics "just in case" selects for resistant bacteria and causes patient harm (allergic reactions, C. difficile, disruption of microbiome). Symptomatic treatment: paracetamol, hydration, rest, saline nasal rinse. This is a core antimicrobial stewardship principle.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','hard','mcq','Carbapenems are "last-resort" antibiotics for multi-drug-resistant Gram-negative infections. Which enzyme produced by some bacteria confers resistance to carbapenems and is a critical AMR threat?','["A. Carbapenemase (e.g., NDM-1, KPC, OXA-48)", "B. Extended-Spectrum Beta-Lactamase (ESBL)", "C. Penicillinase (TEM-1)", "D. Metallo-beta-lactamase targeting only aztreonam"]','A','Carbapenemases are beta-lactamase enzymes capable of hydrolysing carbapenems (Meropenem, Imipenem, Ertapenem) — the drugs of last resort for MDR Gram-negatives. Key carbapenemases: KPC (Klebsiella pneumoniae Carbapenemase), NDM-1 (New Delhi Metallo-beta-lactamase), OXA-48. These are carried on mobile genetic elements (plasmids) enabling rapid inter-species spread. Carbapenem-resistant Enterobacteriaceae (CRE) and Carbapenem-resistant Pseudomonas are WHO Priority 1 Critical pathogens. Treatment options are extremely limited: Colistin, Fosfomycin, Ceftazidime-Avibactam, Cefiderocol, or combination therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Clinicals','Antimicrobial Stewardship','hard','mcq','A 70-year-old patient in ICU on broad-spectrum antibiotics for 10 days develops diarrhoea. Stool testing confirms Clostridioides difficile toxin positive. He has WBC 22,000 cells/µL, creatinine doubled, and CT shows colonic wall thickening. How should severity be classified and how does this affect treatment?','["A. Mild CDI — Oral Metronidazole 500 mg TID for 10 days","B. Severe CDI (WBC >15,000 and rising creatinine) — Oral Vancomycin 125-500 mg QID for 10 days (preferred over Metronidazole for severe disease)","C. Fulminant CDI — IV Metronidazole alone is adequate","D. All CDI is treated identically regardless of severity"]','B','CDI severity classification guides treatment: Mild-Moderate CDI: Oral Metronidazole 500 mg TID for 10 days. Severe CDI (WBC >15,000 cells/µL, serum creatinine >1.5× baseline, or albumin <3 g/dL): Oral Vancomycin 125-500 mg QID for 10 days (superior to Metronidazole for severe disease). Fulminant CDI (hypotension, ileus, megacolon): IV Metronidazole + high-dose oral/rectal Vancomycin; consider surgery (subtotal colectomy). Fidaxomicin is preferred for first recurrence if available. Faecal microbiota transplantation (FMT) for multiple recurrences. Always stop the inciting antibiotic if clinically possible.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
